#include <cstddef>
#include <cstdint>
#include <climits>
namespace{constexpr std::size_t N=12,L=26;void put64(std::uint8_t*o,std::size_t p,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(std::size_t j=0;j<8;j++){o[p+j]=static_cast<std::uint8_t>(b&255U);b>>=8;}}}
extern "C" std::int64_t srpt_flow_time(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap)noexcept{if(!in||len<4||len>L)return -1;auto mr=in[0],nr=in[1];if(mr<1||mr>4||nr<1||nr>N||len!=2+2*static_cast<std::size_t>(nr))return -1;auto machines=static_cast<std::size_t>(mr),n=static_cast<std::size_t>(nr);std::int64_t release[N]{},remaining[N]{},completion[N]{};for(std::size_t i=0;i<n;i++){release[i]=in[2+2*i];remaining[i]=in[3+2*i];if(release[i]<0||release[i]>50||remaining[i]<1||remaining[i]>10)return -1;}auto bytes=8*(1+n);if(!out||cap<bytes)return -2;std::int64_t time=0;std::size_t done=0;while(done<n){bool chosen[N]{};std::size_t selected[N]{},count=0;for(std::size_t machine=0;machine<machines;machine++){std::size_t best=n;for(std::size_t i=0;i<n;i++)if(!chosen[i]&&remaining[i]>0&&release[i]<=time&&(best==n||remaining[i]<remaining[best]||(remaining[i]==remaining[best]&&i<best)))best=i;if(best==n)break;chosen[best]=true;selected[count++]=best;}if(count==0){auto next=INT64_MAX;for(std::size_t i=0;i<n;i++)if(remaining[i]>0&&release[i]<next)next=release[i];time=next;continue;}++time;for(std::size_t j=0;j<count;j++){auto i=selected[j];--remaining[i];if(remaining[i]==0){completion[i]=time;++done;}}}std::int64_t total=0;for(std::size_t i=0;i<n;i++)total+=completion[i]-release[i];put64(out,0,total);for(std::size_t i=0;i<n;i++)put64(out,8*(1+i),completion[i]);return static_cast<std::int64_t>(bytes);}
